Change: func(e ui.ChangeEvent) {
	ids := append([]string{}, state.Scope.Selected...)
	if i < len(ids) {
		ids = append(ids[:i], ids[i+1:]...)
	}
	if e.SelectedID != "__none" {
		for _, id := range ids {
			if id == e.SelectedID {
				return
			}
		}
		at := min(i, len(ids))
		ids = append(ids, "")
		copy(ids[at+1:], ids[at:])
		ids[at] = e.SelectedID
	}
	s.invoke("scope.probes.set", workbench.ProbeParams{IDs: ids})
}

